// FiberServerOptions provides options for the Fiber server.
type FiberServerOptions struct {
	BaseURL            string
	Middlewares        []MiddlewareFunc
	HandlerMiddlewares []HandlerMiddlewareFunc
}

// RegisterHandlers creates http.Handler with routing matching OpenAPI spec.
func RegisterHandlers(router fiber.Router, si ServerInterface) {
	RegisterHandlersWithOptions(router, si, FiberServerOptions{})
}

// RegisterHandlersWithOptions creates http.Handler with additional options
func RegisterHandlersWithOptions(router fiber.Router, si ServerInterface, options FiberServerOptions) {
	wrapper := ServerInterfaceWrapper{
		Handler:            si,
		HandlerMiddlewares: options.HandlerMiddlewares,
	}

	for _, m := range options.Middlewares {
		router.Use(fiber.Handler(m))
	}

	router.Get(options.BaseURL+"/v1/applications", wrapper.ListApplications)

	router.Post(options.BaseURL+"/v1/applications", wrapper.CreateApplication)

	router.Get(options.BaseURL+"/v1/applications/:id", wrapper.GetApplication)

	router.Put(options.BaseURL+"/v1/applications/:id/vehicle", wrapper.SelectVehicle)

	router.Put(options.BaseURL+"/v1/applications/:id/applicant", wrapper.AttachApplicant)

	router.Delete(options.BaseURL+"/v1/applications/:id/consents/:kind", wrapper.RevokeConsent)

	router.Put(options.BaseURL+"/v1/applications/:id/consents/:kind", wrapper.GrantConsent)

	router.Put(options.BaseURL+"/v1/applications/:id/documents/:kind", wrapper.AttachDocument)

	router.Post(options.BaseURL+"/v1/applications/:id/submit", wrapper.SubmitApplication)

	router.Post(options.BaseURL+"/v1/applications/:id/cancel", wrapper.CancelApplication)

	router.Post(options.BaseURL+"/v1/applications/:id/manual-decision", wrapper.ResolveManualReview)

	router.Post(options.BaseURL+"/v1/applications/:id/offer/accept", wrapper.AcceptOffer)

}
